INSERT INTO stretchy_report_parameter (report_id, parameter_id, report_parameter_name)
SELECT sr.id, sp.id, 'officeId' FROM stretchy_report sr JOIN stretchy_parameter sp ON sp.parameter_name = 'OfficeIdSelectOne'
WHERE sr.report_name = 'Multi-tranche pipeline';
